import { RequestMethods, } from '06_shared/types/types';
import { baseQuery } from '06_shared/api/baseQuery';
import { createApi } from '@reduxjs/toolkit/query/react';
import { LS_ACCESS_TOKEN } from '06_shared/constants/localStorage';
import { siteLanguage } from '../lib/siteLanguage';
// Токен сокета тут не запитуємо: WebsocketLoader бере свіжий перед кожним
// підключенням, щойно зʼявиться користувач.
const signIn = (token) => {
    localStorage.setItem(LS_ACCESS_TOKEN, `${token.token_type} ${token.access_token}`);
};
export const isLoginChallenge = (result) => (!!result && 'requires_device_code' in result && result.requires_device_code);
export const userApi = createApi({
    reducerPath: 'userApi',
    tagTypes: ['user', 'websocketToken', 'sessions'],
    baseQuery: baseQuery,
    endpoints: (builder) => ({
        login: builder.mutation({
            query: (body) => {
                const request = { ...body, language: siteLanguage() };
                return {
                    url: '/auth/login',
                    method: RequestMethods.POST,
                    body: request,
                };
            },
            async onQueryStarted(arg, { dispatch, queryFulfilled }) {
                try {
                    const { data } = await queryFulfilled;
                    // Новий пристрій: токенів ще немає, модалка просить код із пошти.
                    if (isLoginChallenge(data.result) || !data.result)
                        return;
                    signIn(data.result);
                    dispatch(userApi.endpoints.getMe.initiate());
                }
                catch (e) {
                    console.error('Error in queryFulfilled login', e);
                }
            },
        }),
        confirmLogin: builder.mutation({
            query: (body) => ({
                url: '/auth/login/confirm',
                method: RequestMethods.POST,
                body,
            }),
            async onQueryStarted(arg, { dispatch, queryFulfilled }) {
                try {
                    const { data } = await queryFulfilled;
                    if (!data.result)
                        return;
                    signIn(data.result);
                    dispatch(userApi.endpoints.getMe.initiate());
                }
                catch (e) {
                    console.error('Error in queryFulfilled confirmLogin', e);
                }
            },
        }),
        signup: builder.mutation({
            query: (body) => ({
                url: '/users',
                method: RequestMethods.POST,
                body,
            }),
        }),
        getMe: builder.query({
            query: () => ({
                url: '/auth/me',
                method: RequestMethods.GET,
            }),
            providesTags: ['user'],
        }),
        getWebsocketToken: builder.query({
            query: () => ({
                url: '/auth/websocket-token',
                method: RequestMethods.POST,
            }),
            providesTags: ['websocketToken'],
        }),
        updateProfile: builder.mutation({
            query: (body) => ({
                url: '/users/me',
                method: RequestMethods.PATCH,
                body,
            }),
            invalidatesTags: ['user'],
        }),
        // Інші сесії бекенд завершує — список сесій перечитуємо.
        changePassword: builder.mutation({
            query: (body) => ({
                url: '/users/me/password',
                method: RequestMethods.POST,
                body,
            }),
            invalidatesTags: ['sessions'],
        }),
        getSessions: builder.query({
            query: () => ({
                url: '/users/me/sessions',
                method: RequestMethods.GET,
            }),
            providesTags: ['sessions'],
        }),
        endSession: builder.mutation({
            query: (sessionUuid) => ({
                url: `/users/me/sessions/${sessionUuid}`,
                method: RequestMethods.DELETE,
            }),
            invalidatesTags: ['sessions'],
        }),
        endOtherSessions: builder.mutation({
            query: () => ({
                url: '/users/me/sessions',
                method: RequestMethods.DELETE,
            }),
            invalidatesTags: ['sessions'],
        }),
        forgotPassword: builder.mutation({
            query: (body) => {
                const request = { ...body, language: siteLanguage() };
                return {
                    url: '/auth/password/forgot',
                    method: RequestMethods.POST,
                    body: request,
                };
            },
        }),
        resetPassword: builder.mutation({
            query: (body) => ({
                url: '/auth/password/reset',
                method: RequestMethods.POST,
                body,
            }),
        }),
    }),
});
export const { useLoginMutation, useConfirmLoginMutation, useSignupMutation, useGetMeQuery, useGetWebsocketTokenQuery, useUpdateProfileMutation, useChangePasswordMutation, useGetSessionsQuery, useEndSessionMutation, useEndOtherSessionsMutation, useForgotPasswordMutation, useResetPasswordMutation, } = userApi;
