import * as yup from 'yup';
import { getPasswordMatchesMessage, password_matches_regex } from '06_shared/utils/other';
// Правила нового пароля — ті самі, що при реєстрації (бекенд:
// UserPasswordBase): ≥ 6 символів, велика й мала літери, цифра й один із
// !@#$%^&*; повтор має збігатися. Ключі перекладу — у просторі імен того,
// хто викликає (t уже прив'язаний до нього).
export const newPasswordFields = (t) => ({
    user_password: yup
        .string()
        .min(6, t('Minimum 6 characters'))
        .required(t('Field is required'))
        .matches(password_matches_regex, getPasswordMatchesMessage(t)),
    user_password_repeat: yup
        .string()
        .required(t('Field is required'))
        .oneOf([yup.ref('user_password')], t('Passwords must match')),
});
